    public static boolean canDisable()
    {
        boolean canDisable = true;

        canDisable = canDisable && !GUPGlobalEnableFeatureHelper::isUnitPriceDiscountAmountSet();

        return canDisable;
    }

    private static boolean isUnitPriceDiscountAmountSet()
    {
        boolean isUsed = false;

        RetailDiscountMultibuy  retailDiscountMultibuy;

        select firstonly RecId, OfferId from retailDiscountMultibuy
            where retailDiscountMultibuy.MultibuyDiscountType == RetailDiscountTypeEnum::UnitPriceDiscAmt;

        if (retailDiscountMultibuy.RecId)
        {
            isUsed = true;
            Message::Add(MessageSeverity::Error, strFmt("@GlobalUnifiedPricing:GUPUnitPriceDiscountAmountUsedError", retailDiscountMultibuy.OfferId));
        }

        return isUsed;
    }
